namespace Orbita.Web.Models.ViewModels;

public sealed record ErrorPageViewModel(
    int StatusCode,
    string Signal,
    string Title,
    string Description,
    string Sector,
    string SuggestedAction,
    bool IsAccessDenied = false)
{
    public static ErrorPageViewModel ForStatusCode(int statusCode) => statusCode switch
    {
        400 => new(statusCode, "НЕВЕРНЫЙ ЗАПРОС", "Запрос не распознан", "Переданные данные имеют неверный формат. Вернитесь к предыдущему шагу и повторите действие.", "Протокол передачи", "Проверьте введённые данные и повторите запрос."),
        401 => new(statusCode, "ТРЕБУЕТСЯ АВТОРИЗАЦИЯ", "Требуется вход", "Сеанс работы не подтверждён или завершён. Войдите в панель, чтобы продолжить.", "Контур доступа", "Войдите в систему и повторите запрос."),
        403 => new(statusCode, "ДОСТУП ОГРАНИЧЕН", "Недостаточно прав", "У вашей учётной записи нет доступа к этому разделу Орбиты.", "Закрытый сектор", "Обратитесь к администратору, чтобы получить нужное разрешение.", true),
        404 => new(statusCode, "СИГНАЛ ПОТЕРЯН", "Страница не найдена", "Похоже, вы попали в область неизвестного сектора. Запрашиваемая страница недоступна или была перемещена.", "Неизвестный сектор", "Проверьте адрес или вернитесь на главную страницу."),
        408 => new(statusCode, "НЕТ ОТВЕТА", "Время ожидания истекло", "Сервис не успел ответить на запрос. Соединение могло быть прервано.", "Канал связи", "Повторите запрос через несколько секунд."),
        429 => new(statusCode, "СЛИШКОМ МНОГО СИГНАЛОВ", "Превышен лимит запросов", "Орбита временно ограничила частоту обращений для защиты системы.", "Контур защиты", "Подождите немного и повторите попытку."),
        500 => new(statusCode, "ВНУТРЕННИЙ СБОЙ", "Ошибка на стороне Орбиты", "Во время обработки запроса произошёл непредвиденный сбой. Команда уже получила сигнал.", "Системное ядро", "Повторите запрос. Если ошибка повторится, сообщите администратору время её возникновения."),
        502 => new(statusCode, "СВЯЗЬ ПРЕРВАНА", "Сервис временно недоступен", "Орбита не получила корректный ответ от внутреннего сервиса.", "Шлюз связи", "Подождите немного и обновите страницу."),
        503 => new(statusCode, "СЕКТОР НА ОБСЛУЖИВАНИИ", "Сервис временно недоступен", "Нужный сервис сейчас перегружен или проходит техническое обслуживание.", "Сервисный сектор", "Попробуйте открыть страницу позже."),
        504 => new(statusCode, "ОТВЕТ НЕ ПОЛУЧЕН", "Превышено время ожидания", "Связанный сервис не успел ответить вовремя.", "Шлюз связи", "Обновите страницу через несколько секунд."),
        _ => new(statusCode, "ОБНАРУЖЕНА АНОМАЛИЯ", "Не удалось обработать запрос", "Орбита столкнулась с непредвиденной ситуацией при обработке запроса.", "Неизвестный сектор", "Повторите запрос или вернитесь на главную страницу.")
    };
}
